sysauto_script.script:
(function executeJob() {
    var taskGR = new GlideRecord('x_1790227_event_ma_event_task');
    var gdt = new GlideDateTime();
    var tomorrow = new GlideDateTime();
    tomorrow.addDaysUTC(1);

    taskGR.addQuery('u_due_date', '>=', gdt);
    taskGR.addQuery('u_due_date', '<=', tomorrow);
    taskGR.addQuery('u_status', '!=', 'Completed');
    taskGR.query();

    while (taskGR.next()) {
        var eventGR = taskGR.u_event_id.getRefRecord();
        if (eventGR && eventGR.u_planner) {
            gs.eventQueue('x_1790227_event_ma.task.due.reminder', eventGR, eventGR.u_planner, taskGR.sys_id);
            gs.print('Reminder sent to Planner: ' + eventGR.u_planner.getDisplayValue() + ' for Task: ' + taskGR.u_task_name);
        }
    }
})();
